var t=`0736-doro-wat`;var n=`world-0736`;var r=`ET`;var o=`eastern-africa`;var a=4;var s=86;var g={en:`Doro Wat`,ua:`Доро ват`};var l={en:`Doro Wat is a Ethiopia classic prepared with yellow onion, niter kibbeh, garlic, ginger root. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Доро ват, страва кухні країни Ефіопія зі складниками: жовта цибуля, пряне масло нітер кіббе, часник, корінь імбиру. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Cook finely chopped onion slowly until deeply softened, then add niter kibbeh, berbere, garlic and ginger to form a rich wat base.`,ua:`Повільно уваріть дрібно нарізану цибулю до повної м’якості, додайте нітр кіббе, бербере, часник та імбир для насиченої основи ват.`,t:[`slow-simmer-reduction`],m:18,i:[[`yellow-onion`,320,`g`],[`niter-kibbeh`,65,`g`],[`garlic`,5,`clove`],[`ginger-root`,25,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`chicken-thigh`,850,`g`],[`berbere`,45,`g`],[`water`,650,`ml`],[`tomato-paste`,30,`g`]]},{en:`Boil the eggs for about 10 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 10 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:10,i:[[`chicken-egg`,4,`pcs`]]},{en:`Prick the peeled hard-boiled eggs and warm them in the chicken stew without breaking them.`,ua:`Наколіть очищені круто зварені яйця й прогрійте їх у курячому рагу, не розламуючи.`,t:[`stewing`],m:10,i:[[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`injera`,4,`pcs`]]}];var d={slug:t,id:n,country:`ET`,region:o,servings:4,minutes:86,title:g,text:l,steps:h};export{r as country,d as default,n as id,s as minutes,o as region,a as servings,t as slug,h as steps,l as text,g as title};